$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$path=Join-Path $root 'source/fabric/src/main/java/com/simibubi/create/content/kinetics/chainConveyor/ChainConveyorBlockEntity.java';$manifestPath=Join-Path $root 'port-changes.json';$text=[IO.File]::ReadAllText($path);$nl=if($text.Contains("`r`n")){"`r`n"}else{"`n"}
$changes=@(
 [pscustomobject]@{from='import com.simibubi.create.api.contraption.transformable.TransformableBlockEntity;';to="import com.simibubi.create.Create;${nl}import com.simibubi.create.api.contraption.transformable.TransformableBlockEntity;"},
 [pscustomobject]@{from='NBTHelper.writeCompoundList(connections, NbtUtils::writeBlockPos)';to='NBTHelper.writeCompoundList(connections, p -> { CompoundTag entry = new CompoundTag(); entry.put("Pos", NbtUtils.writeBlockPos(p)); return entry; })'},
 [pscustomobject]@{from='clientPacket ? ChainConveyorPackage::writeToClient : ChainConveyorPackage::write';to='p -> clientPacket ? p.writeToClient(Create.getRegistryAccess()) : p.write(Create.getRegistryAccess())'},
 [pscustomobject]@{from='c -> connections.add(NbtUtils.readBlockPos(c))';to='c -> connections.add(NbtUtils.readBlockPos(c, "Pos").orElseThrow())'},
 [pscustomobject]@{from='ChainConveyorPackage::read';to='t -> ChainConveyorPackage.read(t, registries)'},
 [pscustomobject]@{from="`t`t`t`tif (i == inv.selected)${nl}`t`t`t`t`tstackInSlot.setTag(null);${nl}";to=''}
)
foreach($c in $changes){if(-not$text.Contains($c.from)){throw "Chain serialization anchor missing: $($c.from)"};$text=$text.Replace($c.from,$c.to)};[IO.File]::WriteAllText($path,$text,[Text.UTF8Encoding]::new($false));$m=Get-Content $manifestPath -Raw|ConvertFrom-Json;$e=$m.files|Where-Object path -eq 'content/kinetics/chainConveyor/ChainConveyorBlockEntity.java';$e.changes=@($e.changes)+$changes;$e.status='Native chain routing, travelling/looping package state and inventory consumption retained; Minecraft 1.21.1 block-position/package registry serialization and component-era stack copying adapted.';$m|ConvertTo-Json -Depth 20|Set-Content $manifestPath -Encoding utf8;Write-Output 'Adapted Chain Conveyor serialization to Minecraft 1.21.1 registry APIs.'
